/**
 * Custom auth instructions, shown on small screens only (the left panel covers this on
 * larger screens).
 *
 * @module     core_auth/local/LoginForm/AuthInstructions
 * @copyright  2026 Andrew Nicols <andrew@nicols.co.uk>
 * @license    http://www.gnu.org/copyleft/gpl.html GNU GPL v3 or later
 */

import React from 'react';

export interface AuthInstructionsProps {
    /** Pre-formatted (HTML) authentication instructions for small screens, if configured. */
    authInstructions?: string | null;
}

export default function AuthInstructions({authInstructions}: AuthInstructionsProps): React.ReactElement | null {
    if (!authInstructions) {
        return null;
    }

    return (
        <div className="d-lg-none small mb-3">
            {/* Auth instructions are configured by an administrator and trusted. */}
            <div dangerouslySetInnerHTML={{__html: authInstructions}} />
        </div>
    );
}
